package main

import (
	"testing"
	"time"
)

// TestWatchKnobs pins the two watcher knob resolvers' env contract
// (watch-scan D5, envDuration's INV-env-defaults): the defaults when unset,
// the default + floor recovery when malformed, the interval's ≤ 0 passthrough
// (run's off position — the watcher disabled alone), and the debounce's 1s
// floor (the autoNextCountdownSeconds floor law — a zero window must never
// fire one scan per event burst).
func TestWatchKnobs(t *testing.T) {
	// No t.Parallel: t.Setenv mutates process env, which the testing package
	// forbids under parallel.
	tests := []struct {
		name       string
		intervalKV string
		debounceKV string
		set        bool
		wantInt    time.Duration
		wantDeb    time.Duration
	}{
		{
			name:    "defaults when both unset",
			wantInt: time.Hour,
			wantDeb: 30 * time.Second,
		},
		{
			name:       "malformed values fall back to the defaults",
			intervalKV: "not-a-duration",
			debounceKV: "soon",
			set:        true,
			wantInt:    time.Hour,
			wantDeb:    30 * time.Second,
		},
		{
			name:       "interval parses verbatim, including the off position",
			intervalKV: "0",
			debounceKV: "45s",
			set:        true,
			wantInt:    0,
			wantDeb:    45 * time.Second,
		},
		{
			name:       "negative interval passes through as disabled",
			intervalKV: "-5m",
			debounceKV: "200ms",
			set:        true,
			wantInt:    -5 * time.Minute,
			wantDeb:    time.Second,
		},
		{
			name:       "debounce floored at one second",
			intervalKV: "15m",
			debounceKV: "500ms",
			set:        true,
			wantInt:    15 * time.Minute,
			wantDeb:    time.Second,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.set {
				t.Setenv("MELLIFERA_WATCH_INTERVAL", tt.intervalKV)
				t.Setenv("MELLIFERA_WATCH_DEBOUNCE", tt.debounceKV)
			}
			if got := watchInterval(); got != tt.wantInt {
				t.Errorf("watchInterval() = %v, want %v", got, tt.wantInt)
			}
			if got := watchDebounce(); got != tt.wantDeb {
				t.Errorf("watchDebounce() = %v, want %v", got, tt.wantDeb)
			}
		})
	}
}
